mapper.select:
SELECT tpd.*, fp.FINPROD_MARKET_ID, fp.FINPROD_NAME, fp.finprod_abbr,/*add by songyawei 20200709 */ fpt.TYPE_6,
fpt.TYPE_9, fpt.TYPE_10, fpt.TYPE_11, prod.MDATE
FROM (
SELECT T1.TRADE_ID, #{VALID_STATUS_01} VALID_STATUS, T1.FINPROD_TYPE2, T1.FINPROD_ID, T1.PS, T1.TRADE_MARKET, T1.TRADE_PLAT, T1.TRADE_MARKET_MODE,T1.TRADE_AMT, T1.PRIN_AMT,T1.SHARE_AMT, T1.CCY, T1.TRADE_DATE, T1.SETTLE_DATE, T1.REMARK,T1.WORKFLOW_ID, null WORKFLOW_STATUS,T1.B_TRADE_ID,T2.ENTRUST_ID,pp.PORTFOLIO_ID,pp.PORTFOLIO_NAME,pp.PARENT_PORTFOLIO_ID,T1.P_TRADE_ID ,T1.TOTLE_TRADE_ID FROM (SELECT * FROM WFL_TRD_PRODUCT_DEAL MINUS SELECT W1.* FROM WFL_TRD_PRODUCT_DEAL W1 INNER JOIN WFL_TRD_PRODUCT_DEAL W2 ON W1.B_TRADE_ID = W2.TRADE_ID WHERE W1.PS = #{PS24}) T1 LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD T2 ON T1.TRADE_ID = T2.TRADE_ID LEFT JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = T2.PORTFOLIO_ID
(T1.IS_CANCEL is null or T1.IS_CANCEL = #{YES_NO_NO}) and T1.TRADE_STATUS = #{TRADESTATUS_NEW} and (T1.is_swap_transaction IS NULL OR T1.is_swap_transaction = #{YES_NO_NO})
UNION ALL SELECT T1.TRADE_ID, #{VALID_STATUS_02} VALID_STATUS, T1.FINPROD_TYPE2, T1.FINPROD_ID, T1.PS, T1.TRADE_MARKET, T1.TRADE_PLAT, T1.TRADE_MARKET_MODE,T1.TRADE_AMT, T1.PRIN_AMT,T1.SHARE_AMT, T1.CCY, T1.TRADE_DATE, T1.SETTLE_DATE, T1.REMARK, null WORKFLOW_ID, null WORKFLOW_STATUS,T1.B_TRADE_ID,T2.ENTRUST_ID,PP.PORTFOLIO_ID, PP.PORTFOLIO_NAME,pp.PARENT_PORTFOLIO_ID,T1.P_TRADE_ID ,T1.TOTLE_TRADE_ID FROM TRD_PRODUCT_DEAL T1 LEFT JOIN TRD_PRODUCT_DEAL_ADD T2 ON T1.TRADE_ID = T2.TRADE_ID LEFT JOIN PTL_TRADE PT ON T1.TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID
PP.INVEST_YESORNO = 'Y' AND (T1.IS_CANCEL is null or T1.IS_CANCEL = #{YES_NO_NO}) and T1.TRADE_STATUS = #{TRADESTATUS_NEW}
UNION ALL SELECT T1.TRADE_ID, #{VALID_STATUS_03} VALID_STATUS, T1.FINPROD_TYPE2, T1.FINPROD_ID, T1.PS, T1.TRADE_MARKET, T1.TRADE_PLAT, T1.TRADE_MARKET_MODE,T1.TRADE_AMT, T1.PRIN_AMT,T1.SHARE_AMT, T1.CCY, T1.TRADE_DATE, T1.SETTLE_DATE, T1.REMARK, null WORKFLOW_ID, null WORKFLOW_STATUS,T1.B_TRADE_ID,T2.ENTRUST_ID,PP.PORTFOLIO_ID, PP.PORTFOLIO_NAME,pp.PARENT_PORTFOLIO_ID,T1.P_TRADE_ID ,T1.TOTLE_TRADE_ID FROM TRD_PRODUCT_DEAL T1 LEFT JOIN TRD_PRODUCT_DEAL_ADD T2 ON T1.TRADE_ID = T2.TRADE_ID LEFT JOIN PTL_TRADE PT ON T1.P_TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID
PP.INVEST_YESORNO = 'Y' AND T1.TRADE_STATUS = #{TRADESTATUS_REVOKE}
) tpd LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = tpd.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = fp.FINPROD_ID LEFT JOIN FIN_PRODUCT prod ON prod.FINPROD_MARKET_ID = tpd.PORTFOLIO_ID and prod.finprod_type2 = 'F16'
fp.FINPROD_TYPE2 = #{COMMON_BUSINESS_TYPE_TRD02} AND fp.PROFIT_TYPE= #{PROFIT_TYPE}
AND (tpd.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUser}) OR tpd.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUser}))
AND ( tpd.PORTFOLIO_ID IN
#{item}
OR tpd.PARENT_PORTFOLIO_ID IN
#{item}
)
AND tpd.ENTRUST_ID like CONCAT(#{entrustId}, '%')
AND fp.FINPROD_MARKET_ID like CONCAT(#{finprodId}, '%')
AND fpt.TYPE_6 = #{type6}
AND fpt.TYPE_9 = #{type9}
AND fpt.TYPE_10 = #{type10}
AND fpt.TYPE_11 = #{type11}
AND tpd.PS in
#{item}
AND tpd.TRADE_DATE >= to_date(#{tradeDateBegin}, 'yyyy-MM-dd')
AND tpd.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
ORDER BY tpd.TRADE_DATE DESC

SELECT T1.FINPROD_ID id, T1.FINPROD_NAME text, T1.FINPROD_NAME, T1.CCY, T1.CALENDAR_ID, TO_CHAR(T1.VDATE, 'yyyy-MM-dd') VDATE, T1.ISSUER, T2.TYPE_6,
T2.TYPE_9, T2.TYPE_10, T2.TYPE_11,
T2.TYPE_7, T3.PUR_SPEED, T3.RED_SPEED, T1.MANAGER, T2.TYPE_12 FROM FIN_PRODUCT T1 LEFT JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD T3 ON T1.FINPROD_ID = T3.FINPROD_ID
(T1.FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) or T1.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')))
AND T1.FINPROD_ID = #{initValue}
AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TG}
AND T1.PROFIT_TYPE = #{PROFIT_TYPE}

select
CLOSE_PRICE
from MST_EXCHARGE_QUOTE
where
BASIS_CYY = #{ccy}
and QUOT_CYY = #{cny}
and TRADE_DATE = #{tradDate}

