SELECT NVL(T1.ENTRUST_AMT,T1.ENTRUST_NUM * 100) entrustAmt, NVL(T1.ENTRUST_NUM,0) entrustNum, NVL(T2.FINISH_AMT,0) finishAmt, NVL(T5.PRIN_AMT,0) prinAmt FROM ETR_ENTRUST T1 LEFT JOIN ( SELECT FINISH_AMT, ENTRUST_ID FROM ETR_FINISH_STATUS
ENTRUST_ID = #{entrustId}
) T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN ( SELECT T4.PRIN_AMT,T3.ENTRUST_ID FROM WFL_TRD_PRODUCT_DEAL_ADD T3 LEFT JOIN WFL_TRD_PRODUCT_DEAL T4 ON T3.TRADE_ID = T4.TRADE_ID
T3.ENTRUST_ID = #{entrustId} AND T4.PS IN (#{pssg},#{pssh})
AND T4.TRADE_ID <> #{tradeId}
) T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID
T1.ENTRUST_ID = #{entrustId}
